diffs.patch:
Index: backup.go
===================================================================
--- backup.go	
+++ backup.go	
@@ -0,0 +1,128 @@
+package backup
+
+import (
+	"fmt"
+	"io"
+	"os"
+	"path/filepath"
+	"sort"
+	"strings"
+	"time"
+)
+
+const (
+	backupDir   = "/var/handoff-backup"
+	keepCount   = 7
+)
+
+func Backup(src string) error {
+	info, err := os.Stat(src)
+	if err != nil {
+		return fmt.Errorf("stat source %q: %w", src, err)
+	}
+
+	if err := os.MkdirAll(backupDir, 0o755); err != nil {
+		return fmt.Errorf("create backup dir %q: %w", backupDir, err)
+	}
+
+	name := time.Now().Format("20060102-150405") + "-" + filepath.Base(src)
+	if info.IsDir() {
+		name += ".dir"
+	} else {
+		name += ".file"
+	}
+	dest := filepath.Join(backupDir, name)
+
+	if info.IsDir() {
+		if err := copyDir(src, dest); err != nil {
+			return err
+		}
+	} else {
+		if err := copyFile(src, dest, info.Mode()); err != nil {
+			return err
+		}
+	}
+
+	return prune()
+}
+
+func prune() error {
+	entries, err := os.ReadDir(backupDir)
+	if err != nil {
+		return fmt.Errorf("read backup dir %q: %w", backupDir, err)
+	}
+	names := make([]string, 0, len(entries))
+	for _, e := range entries {
+		names = append(names, e.Name())
+	}
+	sort.Sort(sort.Reverse(sort.StringSlice(names)))
+
+	excess := names[keepCount:]
+	for _, n := range excess {
+		if err := os.RemoveAll(filepath.Join(backupDir, n)); err != nil {
+			return fmt.Errorf("remove old backup %q: %w", n, err)
+		}
+	}
+	return nil
+}
+
+func copyFile(src, dest string, mode os.FileMode) error {
+	in, err := os.Open(src)
+	if err != nil {
+		return fmt.Errorf("open source %q: %w", src, err)
+	}
+	defer in.Close()
+
+	out, err := os.OpenFile(dest, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, mode)
+	if err != nil {
+		return fmt.Errorf("create dest %q: %w", dest, err)
+	}
+	defer out.Close()
+
+	if _, err := io.Copy(out, in); err != nil {
+		return fmt.Errorf("copy %q to %q: %w", src, dest, err)
+	}
+	return nil
+}
+
+func copyDir(src, dest string) error {
+	if err := os.MkdirAll(dest, 0o755); err != nil {
+		return fmt.Errorf("create dir %q: %w", dest, err)
+	}
+	entries, err := os.ReadDir(src)
+	if err != nil {
+		return fmt.Errorf("read dir %q: %w", src, err)
+	}
+	for _, e := range entries {
+		sp := filepath.Join(src, e.Name())
+		dp := filepath.Join(dest, e.Name())
+		info, err := e.Info()
+		if err != nil {
+			return fmt.Errorf("stat %q: %w", sp, err)
+		}
+		if info.IsDir() {
+			if err := copyDir(sp, dp); err != nil {
+				return err
+			}
+		} else if info.Mode()&os.ModeSymlink != 0 {
+			link, err := os.Readlink(sp)
+			if err != nil {
+				return fmt.Errorf("readlink %q: %w", sp, err)
+			}
+			if err := os.Symlink(link, dp); err != nil {
+				return fmt.Errorf("symlink %q: %w", dp, err)
+			}
+		} else {
+			if err := copyFile(sp, dp, info.Mode()); err != nil {
+				return err
+			}
+		}
+	}
+	return nil
+}
+
+func BackupDir() string   { return backupDir }
+func KeepCount() int      { return keepCount }
+func isBackupName(n string) bool {
+	return strings.HasSuffix(n, ".file") || strings.HasSuffix(n, ".dir")
+}
